            b: ["d", "p", "v", "g"],
            d: ["b", "t", "g", "n"],
            f: ["v", "th", "s", "p"],
            g: ["k", "d", "b", "j"],
            h: ["wh", "f"],
            j: ["g", "ch", "zh", "z"],
            k: ["g", "t", "c", "ck"],
            l: ["r", "w", "n", "y"],
            m: ["n", "b", "p", "ng"],
            n: ["m", "ng", "d", "l"],
            p: ["b", "t", "f", "k"],
            r: ["l", "w", "y", "er"],
            s: ["z", "sh", "th", "f"],
            t: ["d", "k", "p", "ch"],
            v: ["f", "b", "w", "th"],
            w: ["r", "l", "wh", "y"],
            y: ["w", "l", "ee", "i"],
            z: ["s", "zh", "j", "th"],
            sh: ["ch", "s", "zh", "th"],
            ch: ["sh", "j", "t", "tch"],
            th: ["f", "v", "s", "d"],
            wh: ["w", "h", "f"],
            ng: ["n", "m", "nk"],
            ck: ["k", "g", "c"],
            a: ["e", "u", "o", "ah"],
            e: ["i", "a", "u", "eh"],
            i: ["e", "ee", "y", "ih"],
            o: ["u", "a", "aw", "ah"],
            u: ["o", "oo", "a", "uh"],
            ee: ["i", "ea", "e", "y"],
            oo: ["u", "ew", "o"],
            ai: ["ay", "a", "ei"],
            oa: ["o", "ow", "oe"],
            ou: ["ow", "oo", "u"],
            ow: ["ou", "oa", "o"],
            oi: ["oy", "ou", "aw"],
            oy: ["oi", "ow", "o"],
            ar: ["or", "er", "a", "ah"],
            or: ["ar", "er", "aw", "ore"],
            er: ["ar", "or", "ur", "ir"],
            ir: ["er", "ur", "ear"],
            ur: ["er", "ir", "or"],
            aw: ["or", "o", "au", "ow"],
            au: ["aw", "o", "ou"],
            c: ["k", "s", "ck", "g"],
