            "b",
            "d",
            "f",
            "g",
            "h",
            "j",
            "k",
            "l",
            "m",
            "n",
            "p",
            "r",
            "s",
            "t",
            "v",
            "w",
            "z",
            "a",
            "e",
            "i",
            "o",
            "u",
            "sh",
            "ch",
            "th",
